import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def is_perfect_cube(n):
    if n < 0:
        return False
    # Handle the case n=0 separately
    if n == 0:
        return True
    # Use approximations for cube root
    cbrt_n = round(n**(1/3))
    return cbrt_n * cbrt_n * cbrt_n == n

