def check_solution(a1, a2, a3):
    # Check m=1
    S1 = a1 + 2 * a2 + 3 * a3
    if (S1 - 1) <= 0:
        return False
    k1_sq = S1 - 1
    k1 = math.isqrt(k1_sq)
    if k1 * k1 != k1_sq:
        return False

    # Check m=2
    S2 = a1 + 4 * a2 + 9 * a3
    if (S2 - 1) <= 0:
        return False
    k2_cube = S2 - 1

    # Check if k2_cube is a perfect cube
    k2_float = k2_cube**(1/3)
    k2 = round(k2_float)
    if k2**3 != k2_cube:
        return False

    return True

def find_solutions(max_a):
    solutions = []
    # Iterate over a1, a2, a3 starting from 1
    for a1 in range(1, max_a + 1):
        for a2 in range(1, max_a + 1):
            for a3 in range(1, max_a + 1):
                if check_solution(a1, a2, a3):
                    solutions.append((a1, a2, a3))
